import path from "node:path";
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { commandKey, compileChecks } from "./commands.mjs";
import { readJson, resolveProjectPath } from "./filesystem.mjs";
import { invariant } from "./errors.mjs";
import { sourceSnapshot, loadSnapshot } from "./snapshot.mjs";
import { isRunBackedStage, requiredVerificationStages } from "./constants.mjs";

export function checksFor(task) {
  return task.checks || compileChecks(task.verification);
}

export function planDigest(item, plan) {
  const definition = {
    id: item.id, type: item.type, revision: item.revision || 1, flags: item.flags,
    acceptance: item.input.acceptance, authorization: item.authorization,
    mode: plan.mode,
    tasks: plan.tasks.map((task) => ({
      id: task.id, title: task.title, owner: task.owner, risk: task.risk,
      blockedBy: task.blockedBy, writeScopes: task.writeScopes, docsImpact: task.docsImpact,
      checks: checksFor(task), reviewBatch: task.reviewBatch,
    })),
    reviewBatches: plan.reviewBatches,
  };
  return createHash("sha256").update(JSON.stringify(definition)).digest("hex");
}

export async function readEvidence(root, id) {
  const config = await readJson(path.join(root, ".ai-harness/config.json"));
  const file = await resolveProjectPath(root, `${config.workItemsDirectory}/${id}/evidence.jsonl`);
  let raw;
  try { raw = await readFile(file, "utf8"); } catch (error) {
    if (error.code === "ENOENT") return [];
    throw error;
  }
  return raw.split(/\r?\n/).flatMap((line, index) => {
    if (!line.trim()) return [];
    let event;
    try { event = JSON.parse(line); } catch { invariant(false, "INVALID_EVIDENCE_JSONL", `证据第 ${index + 1} 行不是有效 JSON。`); }
    invariant(event.workItemId === id, "INVALID_EVIDENCE_OWNER", "证据归属与工作项不一致。" );
    return [event];
  });
}

export function matchingChecks(plan, taskId, command, args) {
  const key = commandKey(command, args);
  return plan.tasks.filter((task) => (!taskId || task.id === taskId) && task.status !== "DEFERRED")
    .flatMap((task) => checksFor(task).filter((check) => commandKey(check.command, check.args) === key).map((check) => ({ taskId: task.id, checkId: check.id })));
}

export function hasFailedReview(events, item, task = null) {
  return events.some((event) => event.kind === "review" && event.status === "fail" &&
    (event.revision || 1) === (item.revision || 1) && (event.taskId ?? null) === (task?.id ?? null) &&
    (!task || (event.taskAttempt || 1) === (task.attempt || 1)));
}

function stageIsCurrent(item, entry, current, digest, events) {
  const latest = events.findLast((event) => event.kind === "verification" && !event.taskId &&
    event.stage === entry?.stage && (event.revision || 1) === (item.revision || 1));
  return entry?.status === "pass" && entry.source?.digest === current.digest &&
    entry.revision === (item.revision || 1) && entry.planDigest === digest &&
    latest?.id === entry.evidence.at(-1) && latest.status === "pass" &&
    latest.source?.digest === current.digest && latest.planDigest === digest &&
    (!isRunBackedStage(entry.stage) || latest.commandRef === entry.command);
}

export async function verificationReport(root, item, plan, { taskId = null, snapshot = null, events = null } = {}) {
  const current = snapshot || await sourceSnapshot(root);
  const evidence = events || await readEvidence(root, item.id);
  const digest = planDigest(item, plan);
  const latest = new Map();
  for (const event of evidence) {
    if (event.kind !== "command" || (event.revision || 1) !== (item.revision || 1) || !event.command || (taskId && event.taskId !== taskId)) continue;
    const task = plan.tasks.find((candidate) => candidate.id === event.taskId);
    if (task && (event.taskAttempt || 1) !== (task.attempt || 1)) continue;
    latest.set(JSON.stringify([event.taskId, commandKey(event.command.executable, event.command.args)]), event);
  }
  let failed = [...latest.values()].filter((event) =>
    event.command.planDigest === digest &&
    (event.command.source?.digest === current.digest || event.command.sourceAfter?.digest === current.digest) &&
    event.status !== "pass");
  const successful = [...latest.values()].filter((event) =>
    event.status === "pass" && event.command.exitCode === 0 && !event.command.timedOut && !event.command.spawnError && !event.command.signal &&
    event.command.planDigest === digest && event.command.source?.digest === current.digest && event.command.sourceAfter?.digest === current.digest);
  const required = plan.tasks.filter((task) => (!taskId || task.id === taskId) && task.status !== "DEFERRED")
    .flatMap((task) => checksFor(task).map((check) => ({ taskId: task.id, ...check })));
  const positions = new Map(evidence.map((event, index) => [event.id, index]));
  failed = failed.filter((event) => !successful.some((later) => positions.get(later.id) > positions.get(event.id) &&
    commandKey(later.command.executable, later.command.args) === commandKey(event.command.executable, event.command.args) &&
    (!later.taskId || later.taskId === event.taskId)));
  const missing = required.filter((check) => !successful.some((event) =>
    commandKey(event.command.executable, event.command.args) === commandKey(check.command, check.args) &&
    (!event.taskId || event.taskId === check.taskId)));
  const missingStages = requiredVerificationStages(item).filter((name) =>
    !stageIsCurrent(item, item.verification.stages?.find((entry) => entry.stage === name), current, digest, evidence));
  return { ok: required.length > 0 && missing.length === 0 && failed.length === 0, current, planDigest: digest, successful, missing, failed, missingStages };
}

export async function assertVerification(root, item, plan, options = {}) {
  const report = await verificationReport(root, item, plan, options);
  invariant(report.ok, "VERIFICATION_NOT_CURRENT", "计划中的验证尚未针对当前代码全部通过，或存在新的失败。", {
    missing: report.missing.map((check) => ({ taskId: check.taskId, checkId: check.id, command: check.command, args: check.args })),
    failed: report.failed.map((event) => event.id),
  });
  for (const event of report.successful) {
    await loadSnapshot(root, event.command.source);
    await loadSnapshot(root, event.command.sourceAfter);
  }
  return report;
}

export async function assertCommandEvidence(root, item, plan, commandId, options = {}) {
  const events = options.events || await readEvidence(root, item.id);
  const current = options.snapshot || await sourceSnapshot(root);
  const index = events.findIndex((candidate) => candidate.id === commandId);
  const event = events[index];
  const task = plan.tasks.find((candidate) => candidate.id === event?.taskId);
  const command = event?.command;
  const subsequentFailure = command && events.slice(index + 1).some((later) => later.kind === "command" && later.status !== "pass" &&
    (later.revision || 1) === (item.revision || 1) && (!later.taskId || later.taskId === event.taskId) &&
    (!later.taskId || (later.taskAttempt || 1) === (event.taskAttempt || 1)) &&
    commandKey(later.command.executable, later.command.args) === commandKey(command.executable, command.args));
  invariant(event?.kind === "command" && event.status === "pass" && command.exitCode === 0 && !command.timedOut && !command.spawnError && !command.signal &&
    (event.revision || 1) === (item.revision || 1) && (!task || (event.taskAttempt || 1) === (task.attempt || 1)) &&
    (!options.taskId || event.taskId === options.taskId) && command.planDigest === planDigest(item, plan) &&
    command.source?.digest === current.digest && command.sourceAfter?.digest === current.digest && !subsequentFailure &&
    matchingChecks(plan, event.taskId, command.executable, command.args).length > 0,
  "COMMAND_EVIDENCE_INVALID", "命令证据必须匹配计划验证、当前代码和计划版本，且没有随后失败。" );
  await loadSnapshot(root, event.command.source);
  await loadSnapshot(root, event.command.sourceAfter);
  return event;
}

export async function assertVerificationStages(root, item, plan, snapshot) {
  const events = await readEvidence(root, item.id);
  const report = await verificationReport(root, item, plan, { snapshot, events });
  invariant(report.missingStages.length === 0, "STALE_VERIFICATION_STAGE", "验证阶段必须对应同一代码和计划版本。", { missing: report.missingStages });
  for (const stage of item.verification.stages || []) {
    if (!requiredVerificationStages(item).includes(stage.stage)) continue;
    await loadSnapshot(root, stage.source);
    if (isRunBackedStage(stage.stage)) await assertCommandEvidence(root, item, plan, stage.command, { snapshot, events });
  }
}

export function invalidateResults(item, plan, taskId = null) {
  item.verification = { status: "pending", evidence: [], stages: [] };
  item.review = { status: "pending", evidence: [], independent: false };
  item.acceptance = { status: "pending", evidence: [] };
  item.delivery = null;
  if (taskId) {
    const task = plan.tasks.find((candidate) => candidate.id === taskId);
    if (task?.status === "IN_PROGRESS") {
      task.verificationStatus = "pending";
      task.reviewStatus = "pending";
    }
  }
}

    await appendEvent(paths, id, "task-added", { taskId: task.id, reviewBatch: task.reviewBatch });
    return task;
  });
}

export async function approvePlan(root, id, approvalRef) {
  invariant(approvalRef?.trim(), "APPROVAL_REQUIRED", "批准计划必须提供授权引用。" );
  return mutatePlan(root, id, async (plan, item, paths) => {
    assertValidPlan(plan, id, { requireContent: true });
    item.plan.approved = true;
    item.plan.approvalRef = approvalRef;
    await appendEvent(paths, id, "plan-approved", { approvalRef });
  });
}

export async function transitionWorkItem(root, id, target, reason = null) {
  const paths = await workItemPaths(root, id);
  return withFileLock(paths.lock, async () => {
    const item = await readJson(paths.state);
    const plan = (await exists(paths.plan)) ? await readJson(paths.plan) : null;
    assertValidWorkItem(item);
    assertTransitionAllowed(item, target, reason);
    await assertTransitionGates(root, item, plan, target);
    const from = item.status;
    if (target === "DONE") {
      const current = await sourceSnapshot(root);
      const delivery = await prepareDelivery(root, item, plan, current);
      const baseline = await saveSnapshot(root, paths.directory, delivery.baseline);
      item.integrityVersion = 1;
      item.revision ||= 1;
      item.delivery = { source: await saveSnapshot(root, paths.directory, current), baseline, baselineAt: delivery.baselineAt, ownedChanges: delivery.ownedChanges, planDigest: planDigest(item, plan), at: nowIso(), head: (await getGitBaseline(root)).commit };
    }
    if (target === "BLOCKED") {
      item.blocked = { from, reason, at: nowIso() };
    } else if (from === "BLOCKED") {
      item.blocked = null;
    }
    item.status = target;
    item.updatedAt = nowIso();
    item.history.push({
      from,
      to: target,
      at: item.updatedAt,
      reason: target === "BLOCKED" ? reason : from === "BLOCKED" ? "unblocked" : reason || "gate-passed",
      ...(from === "BLOCKED" ? { unblockedTo: target } : {}),
    });
    assertValidWorkItem(item);
    await atomicWriteJson(paths.state, item);
    await appendEvent(paths, id, "state-transition", { from, to: target, reason });
    return item;
  });
}

export async function updateTaskStatus(root, id, taskId, target, { reason = null, approvalRef = null } = {}) {
  return mutatePlan(root, id, async (plan, item, paths) => {
    invariant(item.status === "IMPLEMENTING", "WRONG_STAGE", "任务状态只能在 IMPLEMENTING 阶段推进。" );
    const task = plan.tasks.find((candidate) => candidate.id === taskId);
    invariant(task, "TASK_NOT_FOUND", `任务不存在：${taskId}`);
    assertTaskTransition(plan, task, target, approvalRef);
    if (target === "BLOCKED") invariant(reason?.trim(), "BLOCK_REASON_REQUIRED", "阻塞任务必须提供原因。" );
    const from = task.status;
    task.status = target;
    if (target === "IN_PROGRESS") task.attempt = (task.attempt || 0) + 1;
    if (target === "DEFERRED") task.deferralApproval = approvalRef;
    if (target === "REWORK") {
      task.verificationStatus = "pending";
      task.reviewStatus = "pending";
      delete task.verificationSource;
      delete task.reviewSource;
      invalidateResults(item, plan);
    }

    if (["COMPLETED", "DEFERRED"].includes(target)) {
      for (const candidate of plan.tasks.filter((entry) => entry.status === "PENDING")) {
        if (taskDependenciesComplete(plan, candidate)) candidate.status = "READY";
      }
    }
    assertValidPlan(plan, id, { requireContent: true });
    await appendEvent(paths, id, "task-transition", { taskId, from, to: target, reason, approvalRef });
    return task;
  });
}

function createEvidenceEvent({ id, taskId = null, kind, status, summary, command = null, independent = false, stage = null }) {
  return {
    schemaVersion: 1,
    id: randomUUID(),
    workItemId: id,
    taskId,
    kind,
    status,
    summary,
    timestamp: nowIso(),
    command,
    independent,
    stage,
  };
}

function assertResultStage(item, kind) {
  const requiredStage = {
    verification: "VERIFYING",
    documentation: "VERIFYING",
    review: "CODE_REVIEW",
    acceptance: "READY_FOR_ACCEPTANCE",
    analysis: "ANALYZING",
  }[kind];
  invariant(!requiredStage || item.status === requiredStage, "WRONG_STAGE", `${kind} 结果只能在 ${requiredStage} 阶段记录。`);
}

async function findEvidenceById(paths, evidenceId) {
  let raw = "";
  try {
    raw = await readFile(paths.evidence, "utf8");
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
    return null;
  }
  for (const line of raw.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const event = JSON.parse(line);
    if (event.id === evidenceId) return event;
  }
  return null;
}

export async function recordResult(root, id, { kind, status, summary, taskId = null, independent = false, stage = null, commandRef = null }) {
  invariant(EVIDENCE_KINDS.filter((value) => value !== "command").includes(kind), "INVALID_EVIDENCE_KIND", `不支持的证据类型：${kind}`);
  invariant(RESULT_STATUSES.includes(status), "INVALID_RESULT_STATUS", `无效结果状态：${status}`);
  invariant(summary?.trim(), "EVIDENCE_REQUIRED", "证据摘要不能为空。" );
  if (stage !== null) {
    invariant(kind === "verification", "STAGE_KIND_MISMATCH", "只有 verification 证据支持 --stage。" );
    invariant(taskId === null, "STAGE_TASK_CONFLICT", "验证子阶段是工作项级证据，不能绑定任务。" );
    invariant(VERIFICATION_STAGES.some((entry) => entry.stage === stage), "INVALID_VERIFICATION_STAGE", `未知验证子阶段：${stage}`);
    if (isRunBackedStage(stage)) {
      invariant(typeof commandRef === "string" && commandRef.trim(), "STAGE_RUN_REQUIRED", `${stage} 子阶段必须引用一次 harness run 的通过命令证据（--command <id>）。`);
    } else {
      invariant(commandRef === null, "STAGE_COMMAND_NOT_ALLOWED", `${stage} 子阶段不接受 --command。`);
    }
  } else {
    invariant(commandRef === null, "STAGE_COMMAND_NOT_ALLOWED", "--command 只能与验证子阶段一起使用。" );
  }
  const paths = await workItemPaths(root, id);
  return withFileLock(paths.lock, async () => {
    const item = await readJson(paths.state);
    const plan = (await exists(paths.plan)) ? await readJson(paths.plan) : null;
    assertValidWorkItem(item);
    let task = null;

    if (taskId) {
      invariant(item.status === "IMPLEMENTING", "WRONG_STAGE", "任务证据只能在 IMPLEMENTING 阶段记录。" );
      invariant(plan, "PLAN_REQUIRED", "任务证据需要执行计划。" );
      task = plan.tasks.find((candidate) => candidate.id === taskId);
      invariant(task, "TASK_NOT_FOUND", `任务不存在：${taskId}`);
      invariant(["verification", "review"].includes(kind), "INVALID_TASK_EVIDENCE", "任务只接受 verification 或 review 证据。" );
      const requiredTaskStage = kind === "verification" ? "IN_PROGRESS" : "IN_REVIEW";
      invariant(task.status === requiredTaskStage, "WRONG_TASK_STAGE", `${kind} 证据只能在任务 ${requiredTaskStage} 状态记录。`);
    } else if (kind !== "checkpoint") {
      assertResultStage(item, kind);
    }

    // codegen 工作项或 BUGFIX 类型的工作项级 verification 必须走子阶段流水线，禁止裸记录绕过。
    if (kind === "verification" && !taskId && usesVerificationPipeline(item)) {
      invariant(stage !== null, "VERIFICATION_STAGE_REQUIRED", "该工作项必须用 --stage 记录验证子阶段。" );
    }

    if (kind === "review" && status === "pass") {
      invariant(!hasFailedReview(await readEvidence(root, id), item, task), "REVIEW_REWORK_REQUIRED",
        task ? "审查失败后必须先 REWORK，再开始新的任务尝试。" : "最终审查失败后必须先 reopen，建立新修订再验证和审查。");
    }

    let verificationSource = null;
    if (status === "pass" && isDevelopmentType(item.type) && ["verification", "review", "acceptance"].includes(kind)) {
      if (kind !== "verification" || stage === null) await assertVerification(root, item, plan, { taskId });
      verificationSource = await saveSnapshot(root, paths.directory, await sourceSnapshot(root));
      if (stage && item.verification.source && item.verification.source.digest !== verificationSource.digest) invalidateResults(item, plan);
    }

    // 顺序守卫：把某阶段记为 pass 前，其之前的所有“必需”阶段必须已 pass。
    if (stage !== null && status === "pass") {
      const requiredNames = requiredVerificationStages(item);
      const order = VERIFICATION_STAGES.map((entry) => entry.stage);
      const priorRequired = order.slice(0, order.indexOf(stage)).filter((name) => requiredNames.includes(name));
      const statusByStage = new Map((item.verification.stages || []).map((entry) => [entry.stage, entry.status]));
      const missing = priorRequired.filter((name) => statusByStage.get(name) !== "pass");
      invariant(missing.length === 0, "VERIFICATION_STAGE_ORDER", `子阶段 ${stage} 之前的必需阶段尚未通过：${missing.join(", ")}`, { missing });
    }

    // run-backed 阶段（reproduction/regression）必须引用一条真实通过的命令证据。
    if (stage !== null && isRunBackedStage(stage)) {
      const commandEvent = await findEvidenceById(paths, commandRef);
      invariant(commandEvent && commandEvent.kind === "command" && commandEvent.workItemId === id, "STAGE_RUN_EVIDENCE_INVALID", `--command 未指向本工作项的命令证据：${commandRef}`);
      if (status === "pass") {
        invariant(commandEvent.status === "pass", "STAGE_RUN_EVIDENCE_NOT_PASSING", `${stage} 记为 pass 需引用通过的命令证据，但 ${commandRef} 未通过。`);
        await assertCommandEvidence(root, item, plan, commandRef);
      }
    }

    const event = createEvidenceEvent({ id, taskId, kind, status, summary, independent, stage });
    event.revision = item.revision || 1;
    event.taskAttempt = task ? task.attempt || 1 : null;
    if (commandRef) event.commandRef = commandRef;
    if (verificationSource) {
      event.source = verificationSource;
      event.planDigest = planDigest(item, plan);
    }
    await appendJsonLine(paths.evidence, event);

    if (task) {
      if (kind === "verification") task.verificationStatus = status;
      if (kind === "review") task.reviewStatus = status;
      if (verificationSource) task[`${kind}Source`] = verificationSource;
      task.evidence.push(event.id);
      plan.updatedAt = nowIso();
      assertValidPlan(plan, id, { requireContent: true });
      await atomicWriteJson(paths.plan, plan);
    } else if (stage !== null) {
      const stages = item.verification.stages || (item.verification.stages = []);
      let entry = stages.find((candidate) => candidate.stage === stage);
      if (!entry) {
        entry = { stage, status, evidence: [], command: null };
        stages.push(entry);
      } else {
        entry.status = status;
      }
      entry.evidence.push(event.id);
      entry.revision = event.revision;
      if (verificationSource) {
        entry.source = verificationSource;
